#!/usr/bin/env bash
set -Eeuo pipefail
clear

EXPECTED_HOST="pincabos"
EXPECTED_IP="192.168.254.237"

APP_DIR="/opt/pincabos/web"
MODULE="$APP_DIR/pincaboslink.py"
APP="$APP_DIR/app.py"
WEB_SERVICE="pincabos-webapp.service"

STATE="/var/lib/pincabos-link/device.json"
HEARTBEAT_CLIENT="/opt/pincabos/bin/pincabos-link-heartbeat"
HEARTBEAT_SERVICE="/etc/systemd/system/pincabos-link-heartbeat.service"
HEARTBEAT_TIMER="/etc/systemd/system/pincabos-link-heartbeat.timer"

BRIDGE="/usr/local/sbin/pincabos-account-bridge"
DISPLAY_HELPER="/usr/local/sbin/pincabos-chat-backglass"
AGENT="/usr/local/sbin/pincabos-chat-backglass-agent"
AGENT_SERVICE="/etc/systemd/system/pincabos-chat-backglass-agent.service"
SUDOERS="/etc/sudoers.d/pincabos-account-mirror"

STAMP="$(date -u +%Y%m%d-%H%M%S)"
BACKUP="/opt/pincabos/backups/account-mirror-chat-backglass-$STAMP"
ROLLBACK="$BACKUP/ROLLBACK_ACCOUNT_MIRROR_CHAT_BACKGLASS.sh"
STAGE="$(mktemp -d /tmp/pincabos-account-mirror-chat.XXXXXX)"
APPLIED=0

fail(){ echo; echo "==============================================================="; echo " NOGO [ERREUR] $1"; echo "==============================================================="; exit 1; }
cleanup(){ rm -rf "$STAGE"; }
on_error(){ local rc=$?; trap - ERR; if [[ "$APPLIED" -eq 1 && -x "$ROLLBACK" ]]; then echo; echo "Rollback automatique..."; "$ROLLBACK" || true; fi; cleanup; exit "$rc"; }
trap on_error ERR
trap cleanup EXIT

echo "==============================================================="
echo " PINFORGE-SAFE-1A1-450B"
echo " PINCABOS LINK - MON COMPTE LIVE + CHAT PARTAGE + BACKGLASS"
echo " AUCUN IFRAME"
echo " TOKEN ROOT-ONLY"
echo " BACKUP + ROLLBACK + VALIDATION"
echo "==============================================================="

echo
echo "=== 1. GARDES CABINET ==="
[[ "$(id -u)" -eq 0 ]] || fail "Executer avec sudo."
[[ "$(hostname | tr '[:upper:]' '[:lower:]')" == "$EXPECTED_HOST" ]] || fail "Cabinet inattendu."
hostname -I | tr ' ' '\n' | grep -Fxq "$EXPECTED_IP" || fail "IP cabinet absente."
[[ -f "$MODULE" ]] || fail "pincaboslink.py absent."
[[ -f "$APP" ]] || fail "app.py absent."
[[ -f "$STATE" ]] || fail "Ce PinCab n'est pas lie."
[[ "$(stat -c '%U:%G:%a' "$STATE")" == "root:root:600" ]] || fail "Permissions device.json inattendues."
grep -Fq 'PINCABOS_LINK_UI_V3_NATIVE_SHELL' "$MODULE" || grep -Fq 'PINCABOS_LINK_UI_V4_ACCOUNT_MIRROR_CHAT' "$MODULE" || fail "PinCabOS Link Native Shell attendu."
grep -Fq 'register_pincaboslink(app, page)' "$APP" || fail "Enregistrement PinCabOS Link natif absent."
systemctl is-active --quiet "$WEB_SERVICE" || fail "WebApp inactive."
systemctl is-active --quiet pincabos-link-heartbeat.timer || fail "Heartbeat timer inactif."
result="$(curl -sS --max-time 12 -o /dev/null -w '%{http_code}|%{content_type}' https://pincabos.cc/api/device/account-mirror/context || true)"
echo "API 450A anonyme : $result"
[[ "$result" == 401\|application/json* ]] || fail "450A n'est pas actif sur pincabos.cc."
echo "GO [OK] Cabinet et serveur 450A confirmes."

echo
echo "=== 2. BACKUP + PREUVES ==="
mkdir -p "$BACKUP"
cp -a "$MODULE" "$BACKUP/pincaboslink.py.before"
sha256sum "$STATE" > "$BACKUP/device-state.before.sha256"
sha256sum "$HEARTBEAT_CLIENT" "$HEARTBEAT_SERVICE" "$HEARTBEAT_TIMER" > "$BACKUP/heartbeat.before.sha256"

backup_optional(){
    local path="$1" key="$2"
    if [[ -e "$path" ]]; then
        cp -a "$path" "$BACKUP/$key.before"
    else
        touch "$BACKUP/$key.absent"
    fi
}
backup_optional "$BRIDGE" bridge
backup_optional "$DISPLAY_HELPER" display
backup_optional "$AGENT" agent
backup_optional "$AGENT_SERVICE" agent-service
backup_optional "$SUDOERS" sudoers

printf '%s\n' "$(systemctl is-enabled pincabos-chat-backglass-agent.service 2>/dev/null || true)" > "$BACKUP/agent.enabled.before"
printf '%s\n' "$(systemctl is-active pincabos-chat-backglass-agent.service 2>/dev/null || true)" > "$BACKUP/agent.active.before"

cat > "$ROLLBACK" <<ROLLBACK
#!/usr/bin/env bash
set -Eeuo pipefail
clear

systemctl disable --now pincabos-chat-backglass-agent.service 2>/dev/null || true

if [[ -x "$DISPLAY_HELPER" ]]; then
    "$DISPLAY_HELPER" close >/dev/null 2>&1 || true
fi

cp -a "$BACKUP/pincaboslink.py.before" "$MODULE"

restore_optional(){
    local path="\$1" key="\$2"
    if [[ -f "$BACKUP/\$key.absent" ]]; then
        rm -f "\$path"
    else
        cp -a "$BACKUP/\$key.before" "\$path"
    fi
}
restore_optional "$BRIDGE" bridge
restore_optional "$DISPLAY_HELPER" display
restore_optional "$AGENT" agent
restore_optional "$AGENT_SERVICE" agent-service
restore_optional "$SUDOERS" sudoers

visudo -c
systemctl daemon-reload

before_enabled="\$(cat "$BACKUP/agent.enabled.before" 2>/dev/null || true)"
before_active="\$(cat "$BACKUP/agent.active.before" 2>/dev/null || true)"

if [[ "\$before_enabled" == "enabled" ]]; then
    systemctl enable pincabos-chat-backglass-agent.service
fi
if [[ "\$before_active" == "active" ]]; then
    systemctl restart pincabos-chat-backglass-agent.service
fi

python3 -m py_compile "$MODULE"
systemctl restart "$WEB_SERVICE"

for attempt in {1..40}; do
    if systemctl is-active --quiet "$WEB_SERVICE" &&
       curl -fsS --max-time 3 http://127.0.0.1/pincabos-link >/dev/null 2>&1; then
        break
    fi
    sleep 1
done

systemctl is-active --quiet "$WEB_SERVICE"
echo "GO [OK] Rollback 450B termine."
ROLLBACK
chmod 0750 "$ROLLBACK"
echo "Backup  : $BACKUP"
echo "Rollback: $ROLLBACK"
echo "GO [OK] Backup cree."

echo
echo "=== 3. STAGING FICHIERS ==="
printf '%s' '' | base64 -d > "$STAGE/pincaboslink.py"
printf '%s' '' | base64 -d > "$STAGE/pincabos-account-bridge"
printf '%s' '' | base64 -d > "$STAGE/pincabos-chat-backglass"
printf '%s' '' | base64 -d > "$STAGE/pincabos-chat-backglass-agent"

cat > "$STAGE/pincabos-chat-backglass-agent.service" <<'UNIT'
[Unit]
Description=PinCabOS Chat BackGlass Agent
After=network-online.target graphical.target pincabos-webapp.service
Wants=network-online.target

[Service]
Type=simple
ExecStart=/usr/local/sbin/pincabos-chat-backglass-agent
Restart=always
RestartSec=5
NoNewPrivileges=true

[Install]
WantedBy=multi-user.target
UNIT

cat > "$STAGE/pincabos-account-mirror.sudoers" <<'SUDOERS'
# PinCabOS account mirror: exact helpers only
pinball ALL=(root) NOPASSWD: /usr/local/sbin/pincabos-account-bridge *
pinball ALL=(root) NOPASSWD: /usr/local/sbin/pincabos-chat-backglass *
SUDOERS

chmod 0755 "$STAGE/pincabos-account-bridge" "$STAGE/pincabos-chat-backglass" "$STAGE/pincabos-chat-backglass-agent"
chmod 0440 "$STAGE/pincabos-account-mirror.sudoers"

python3 - "$STAGE/pincaboslink.py" "$STAGE/pincabos-account-bridge" "$STAGE/pincabos-chat-backglass-agent" <<'PY'
import ast, sys
from pathlib import Path
for item in sys.argv[1:]:
    path=Path(item); text=path.read_text(encoding="utf-8"); ast.parse(text,filename=str(path))
print("GO [OK] Sources Python staged valides.")
PY
bash -n "$STAGE/pincabos-chat-backglass"
visudo -cf "$STAGE/pincabos-account-mirror.sudoers"

python3 - "$STAGE/pincaboslink.py" <<'PY'
from pathlib import Path
import re, subprocess, sys, tempfile
text=Path(sys.argv[1]).read_text(encoding="utf-8")
required=("PINCABOS_LINK_UI_V4_ACCOUNT_MIRROR_CHAT","PINCABOS_LINK_ACCOUNT_MIRROR_CHAT_V1","/pincabos-link/api/context","/pincabos-link/api/chat/<int:friend_user_id>","/pincabos-link/chat-backglass","Afficher le chat au BackGlass")
for marker in required:
    if marker not in text: raise SystemExit("NOGO [ERREUR] Marqueur module absent : "+marker)
scripts=re.findall(r"<script>\n(.*?)\n</script>",text,re.S)
if len(scripts)!=2: raise SystemExit("NOGO [ERREUR] Nombre de scripts JS inattendu.")
node=__import__("shutil").which("node")
if node:
    for idx,script in enumerate(scripts,1):
        script=script.replace("__CSRF_JS__","testtoken")
        with tempfile.NamedTemporaryFile("w",suffix=".js",delete=False,encoding="utf-8") as fh:
            fh.write(script); name=fh.name
        result=subprocess.run([node,"--check",name],capture_output=True,text=True)
        Path(name).unlink(missing_ok=True)
        if result.returncode!=0: raise SystemExit("NOGO [ERREUR] JS "+str(idx)+" invalide: "+result.stderr)
print("GO [OK] Contrat UI + JavaScript valides.")
PY

echo
echo "=== 4. DEPLOIEMENT HELPERS + MODULE ==="
APPLIED=1
install -o root -g root -m 0644 "$STAGE/pincaboslink.py" "$MODULE"
install -o root -g root -m 0755 "$STAGE/pincabos-account-bridge" "$BRIDGE"
install -o root -g root -m 0755 "$STAGE/pincabos-chat-backglass" "$DISPLAY_HELPER"
install -o root -g root -m 0755 "$STAGE/pincabos-chat-backglass-agent" "$AGENT"
install -o root -g root -m 0644 "$STAGE/pincabos-chat-backglass-agent.service" "$AGENT_SERVICE"
install -o root -g root -m 0440 "$STAGE/pincabos-account-mirror.sudoers" "$SUDOERS"

python3 -m py_compile "$MODULE" "$BRIDGE" "$AGENT"
bash -n "$DISPLAY_HELPER"
visudo -c
systemctl daemon-reload
echo "GO [OK] Fichiers installes."

echo
echo "=== 5. VALIDATION DROITS + GEOMETRIE BACKGLASS ==="
[[ "$(stat -c '%U:%G:%a' "$BRIDGE")" == "root:root:755" ]] || fail "Droits bridge invalides."
[[ "$(stat -c '%U:%G:%a' "$DISPLAY_HELPER")" == "root:root:755" ]] || fail "Droits helper BackGlass invalides."
[[ "$(stat -c '%U:%G:%a' "$SUDOERS")" == "root:root:440" ]] || fail "Droits sudoers invalides."
sudo -l -U pinball 2>/dev/null | grep -Fq "$BRIDGE" || fail "Bridge non autorise au WebApp."
sudo -l -U pinball 2>/dev/null | grep -Fq "$DISPLAY_HELPER" || fail "BackGlass helper non autorise au WebApp."
GEOM="$("$DISPLAY_HELPER" geometry)"
echo "BackGlass geometry : $GEOM"
[[ "$GEOM" == "3840 0 1920 1080" ]] || fail "Geometrie BackGlass inattendue."
echo "GO [OK] Droits minimaux et BackGlass confirmes."

echo
echo "=== 6. TEST AUTHENTIFIE DU MIRROR - AUCUNE VALEUR PRIVEE AFFICHEE ==="
sudo -u pinball sudo -n "$BRIDGE" context > "$BACKUP/context-validation.json"
python3 - "$BACKUP/context-validation.json" <<'PY'
import json,sys
from pathlib import Path
data=json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
if data.get("ok") is not True: raise SystemExit("NOGO [ERREUR] Device Mirror authentifie refuse: "+str(data.get("error")))
if not isinstance(data.get("user"),dict): raise SystemExit("NOGO [ERREUR] user absent.")
if not isinstance(data.get("cabinets"),list): raise SystemExit("NOGO [ERREUR] cabinets absent.")
if not isinstance(data.get("friends"),list): raise SystemExit("NOGO [ERREUR] friends absent.")
print("GO [OK] Compte live recu de pincabos.cc.")
print("GO [OK] Cabinets recus :",len(data["cabinets"]))
print("GO [OK] Amis recus     :",len(data["friends"]))
print("GO [OK] Chat interval  :",data.get("realtime",{}).get("chat_interval_seconds"))
PY
rm -f "$BACKUP/context-validation.json"

echo
echo "=== 7. RESTART WEBAPP + AGENT BACKGLASS ==="
systemctl restart "$WEB_SERVICE"
systemctl enable --now pincabos-chat-backglass-agent.service

READY=0
for attempt in {1..40}; do
    if systemctl is-active --quiet "$WEB_SERVICE" &&
       curl -fsS --max-time 3 -o "$BACKUP/pincabos-link-after.html" http://127.0.0.1/pincabos-link; then
        READY=1
        break
    fi
    sleep 1
done
[[ "$READY" -eq 1 ]] || fail "WebApp non revenue."
systemctl is-active --quiet pincabos-chat-backglass-agent.service || fail "Agent BackGlass inactif."
echo "GO [OK] WebApp et agent BackGlass actifs."

echo
echo "=== 8. VALIDATION INTERFACE ==="
python3 - "$BACKUP/pincabos-link-after.html" <<'PY'
from pathlib import Path
import sys
text=Path(sys.argv[1]).read_text(encoding="utf-8",errors="replace")
required=("PINCABOS_LINK_ACCOUNT_MIRROR_CHAT_V1","Mon compte pincabos.cc","Mes PinCabs","Amis et demandes","Chat PinCabOS","Afficher le chat au BackGlass","JOINDRE","Ouvrir VPinFE","PinCab Explorer","Soutenir PinCabOS")
missing=[x for x in required if x not in text]
if missing: raise SystemExit("NOGO [ERREUR] Elements UI absents: "+", ".join(missing))
print("GO [OK] Replica Mon compte presente.")
print("GO [OK] Chat PinCabOS present.")
print("GO [OK] Bouton BackGlass present.")
print("GO [OK] Shell natif WebApp conserve.")
PY

curl -fsS --max-time 5 http://127.0.0.1/pincabos-link/chat-backglass | grep -Fq 'Chat PinCabOS BackGlass' || fail "Page chat BackGlass absente."
echo "GO [OK] Page dediee BackGlass presente."

echo
echo "=== 9. PREUVES JETON / HEARTBEAT INCHANGES ==="
(cd / && sha256sum -c "$BACKUP/device-state.before.sha256")
(cd / && sha256sum -c "$BACKUP/heartbeat.before.sha256")
echo "GO [OK] Jeton local strictement inchange."
echo "GO [OK] Heartbeat strictement inchange."

echo
echo "=== 10. ETAT BACKGLASS SYNCHRONISE ==="
REMOTE_STATE="$(sudo -u pinball sudo -n "$BRIDGE" backglass-get)"
python3 - "$REMOTE_STATE" <<'PY'
import json,sys
data=json.loads(sys.argv[1])
if data.get("ok") is not True: raise SystemExit("NOGO [ERREUR] Etat BackGlass distant invalide.")
print("Etat demande sur pincabos.cc :", "ACTIF" if data.get("enabled") else "DESACTIVE")
PY
echo "Fenetre locale : $("$DISPLAY_HELPER" status)"

APPLIED=0
trap - ERR

echo
echo "==============================================================="
echo " GO [OK] 450B - MON COMPTE + CHAT + BACKGLASS ACTIFS"
echo "==============================================================="
echo " PAGE : http://192.168.254.237/pincabos-link"
echo
echo " Fonctionnement :"
echo " - valeurs Mon compte lues en direct sur pincabos.cc"
echo " - aucun iframe"
echo " - memes conversations que le site"
echo " - polling chat toutes les 4 secondes"
echo " - bouton Afficher le chat au BackGlass dans le cabinet"
echo " - toggle pincabos.cc synchronise par agent toutes les 5 secondes"
echo " - fenetre dediee sur DP-1 1920x1080+3840+0"
echo
echo " Backup  : $BACKUP"
echo " Rollback: $ROLLBACK"
echo "==============================================================="
